#pragma once

#include <memory>
#include <string>
#include <vector>

struct Node {
  std::string name;
  std::shared_ptr<Node> parent;
  std::vector<std::shared_ptr<Node>> children;
};

inline void attach(const std::shared_ptr<Node>& parent, const std::shared_ptr<Node>& child) {
  child->parent = parent;
  parent->children.push_back(child);
}

